            sql: '{{#if (eq (splitPart param.split_part) "last")}}RIGHT({{field param.source_file param.field_name alias=param.source_alias}}, CHARINDEX(REVERSE({{quote (orEmpty (splitDelimiterChar param) (placeholder "delimiter" "[delimiter]"))}}), REVERSE({{quote (orEmpty (splitDelimiterChar param) (placeholder "delimiter" "[delimiter]"))}} + {{field param.source_file param.field_name alias=param.source_alias}})) - 1){{else if (eq (splitPart param.split_part) 1)}}LEFT({{field param.source_file param.field_name alias=param.source_alias}}, CHARINDEX({{quote (orEmpty (splitDelimiterChar param) (placeholder "delimiter" "[delimiter]"))}}, {{field param.source_file param.field_name alias=param.source_alias}} + {{quote (orEmpty (splitDelimiterChar param) (placeholder "delimiter" "[delimiter]"))}}) - 1){{else}}(SELECT [value] FROM STRING_SPLIT({{field param.source_file param.field_name alias=param.source_alias}}, {{quote (orEmpty (splitDelimiterChar param) (placeholder "delimiter" "[delimiter]"))}}, 1) WHERE [ordinal] = {{splitPart param.split_part}}){{/if}}',
