              sql: '{{#if (eq (splitPart param.split_part) "last")}}RIGHT({{field param.source_file param.field_name alias=param.source_alias}}, (LEN({{field param.source_file param.field_name alias=param.source_alias}})-1) % {{splitWidth param.split_width}} + 1){{else}}SUBSTRING({{field param.source_file param.field_name alias=param.source_alias}}, {{#if (splitWidthSet param.split_width)}}{{plus (times (minus (splitPart param.split_part) 1) (splitWidth param.split_width)) 1}}{{else}}{{minus (splitPart param.split_part) 1}}*{{splitWidth param.split_width}}+1{{/if}}, {{splitWidth param.split_width}}){{/if}}',
